fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
fn owned(case:&serde_json::Value)->ChartSnapshot{ChartSnapshot{chart:DslValue::from(&case["snapshot"]["chart"])}}
fn exact(actual:&DslValue,expected:&DslValue){match(actual,expected){
 (DslValue::Number(Number::UInt(a)),DslValue::Number(Number::UInt(b)))=>assert_eq!(a,b),
 (DslValue::Number(Number::Int(a)),DslValue::Number(Number::Int(b)))=>assert_eq!(a,b),
 (DslValue::Number(Number::Float(a)),DslValue::Number(Number::Float(b)))=>assert_eq!(a.to_bits(),b.to_bits()),
 (DslValue::Array(a),DslValue::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){exact(a,b);}},
 (DslValue::Object(a),DslValue::Object(b))=>{assert_eq!(a.len(),b.len());for(key,value)in b{let matches:Vec<_>=a.iter().filter(|(name,_)|name==key).collect();assert_eq!(matches.len(),1,"duplicate or missing domain member {key}");exact(&matches[0].1,value);}},
