fn independent(script:&str,bytes:&[u8])->Vec<u8>{let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let write=child.stdin.take().unwrap().write_all(bytes);let result=child.wait_with_output().unwrap();assert!(write.is_ok()&&result.status.success(),"independent Chart oracle write={write:?}; stderr={}",String::from_utf8_lossy(&result.stderr));result.stdout}
